contracts/modules/EventRegistry/EventReg.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.27;

// Uncomment this line to use console.log
// import "hardhat/console.sol";
import './Structs.sol';
import './dto/requests.sol';
import './dto/responses.sol';
import '@openzeppelin/contracts/utils/Strings.sol';
import '@openzeppelin/contracts/utils/math/SafeCast.sol';
import {IEventRegistry} from '../../interfaces/IEventRegistry.sol';
import {ITicketNFT} from '../../interfaces/ITicketNFT.sol';
import {ISpecialMomentNFT} from '../../interfaces/ISpecialMomentNFT.sol';
import {IERC20} from '@openzeppelin/contracts/token/ERC20/IERC20.sol';
import {DebugBase} from '../../utils/DebugBase.sol';
import '@openzeppelin/contracts/access/Ownable.sol';

contract EventRegistry is IEventRegistry, Ownable {
    Event[] public events;

    mapping(address => uint64[]) public ownerEvents;

    mapping(uint64 => TicketCategory[]) public ticketCategoriesPerEvent;
    mapping(uint64 => SpecialMomentCollection[])
        public momentCollectionPerEvent;

    address public ticketContract;
    address public ftContract;
    address public specialMomentContract;

    event EventCreated(EventResponse eventResponse);
    event TicketPurchased(TicketPurchasedDto purchase);

    uint256 public platformFee; // Platform fee in basis points (1/100th of a percent)
    address public platformFeeReceiver;
    bool public isPlatformFeeEnabled;

    constructor(
        address _ticketContract,
        address _ftContract,
        address _specialMomentContract,
        address _platformFeeReceiver
    ) Ownable(msg.sender) {
        ticketContract = _ticketContract;
        ftContract = _ftContract;
        specialMomentContract = _specialMomentContract;
        platformFee = 100;
        isPlatformFeeEnabled = true;
        platformFeeReceiver = _platformFeeReceiver;
    }

    modifier onlyPlatformFeeReceiver() {
        require(
            msg.sender == platformFeeReceiver,
            'Only platform fee receiver can call'
        );
        _;
    }

    function togglePlatformFee(
        bool _isEnabled
    ) external onlyPlatformFeeReceiver {
        isPlatformFeeEnabled = _isEnabled;
    }

    function setPlatformFee(
        uint256 _platformFee
    ) external onlyPlatformFeeReceiver {
        require(_platformFee <= 1000, 'Platform fee cannot exceed 10%');
        platformFee = _platformFee;
    }

    modifier onlyEventOwner(uint256 eventId) {
        require(
            msg.sender == events[eventId].owner,
            'Only event owner can modify'
        );
        _;
    }

    function createEvent(
        EventCreationDto memory dto
    ) external returns (uint256) {
        require(
            dto.ticketCategories.length > 0,
            'At least one ticket category is required'
        );
        require(
            dto.startAt >= block.timestamp,
            'Start date must be in the future'
        );
        require(
            dto.endAt > dto.startAt,
            'End time must be after start time in the future'
        );
        require(bytes(dto.title).length > 0, 'Title cannot be empty');

        uint64 eventId = uint64(events.length);

        ownerEvents[msg.sender].push(eventId);
        events.push(
            Event({
                id: eventId,
                title: dto.title,
                description: dto.description,
                royalty: dto.royalty,
                owner: msg.sender,
                startAt: dto.startAt,
                endAt: dto.endAt,
                baseUri: dto.baseUri,
                eventCategory: dto.eventCategory,
                eventSubcategory: dto.eventSubcategory,
                location: EventLocation({
                    hasVenue: dto.location.hasVenue,
                    place: dto.location.place,
                    venue: dto.location.venue,
                    city: dto.location.city,
                    country: dto.location.country
                })
            })
        );

        uint256 ticketCategoriesLength = dto.ticketCategories.length;
        for (uint64 i = 0; i < ticketCategoriesLength; i++) {
            TicketCategoryDto memory categoryDto = dto.ticketCategories[i];

            ticketCategoriesPerEvent[eventId].push(
                TicketCategory({
                    id: i + 1,
                    name: categoryDto.name,
                    copies: categoryDto.copies,
                    ticketCount: 0,
                    price: categoryDto.price,
                    seatIds: new uint256[](0)
                })
            );
        }

        emit EventCreated(_getEventById(eventId));
        return eventId;
    }

    function updateEvent(
        uint64 eventId,
        string memory _title,
        string memory _description,
        uint256 _startAt,
        uint256 _endAt,
        string memory _eventCategory,
        string memory _eventSubcategory
    ) external onlyEventOwner(eventId) {
        require(bytes(_title).length > 0, 'Title cannot be empty');
        require(_startAt > block.timestamp, 'Start date must be in the future');
        require(
            _endAt > _startAt,
            'End time must be after start time in the future'
        );

        // Update event details
        Event storage eventToUpdate = events[eventId];
        eventToUpdate.title = _title;
        eventToUpdate.description = _description;
        eventToUpdate.startAt = _startAt;
        eventToUpdate.endAt = _endAt;
        eventToUpdate.eventCategory = _eventCategory;
        eventToUpdate.eventSubcategory = _eventSubcategory;
    }

    function getEventById(
        uint64 eventId
    ) external view returns (EventResponse memory) {
        return _getEventById(eventId);
    }

    function _getEventById(
        uint64 eventId
    ) internal view returns (EventResponse memory) {
        require(eventId < events.length, 'Event does not exist');
        Event storage event_ = events[eventId];
        TicketCategory[] storage categories = ticketCategoriesPerEvent[eventId];

        uint256 catlen = categories.length;

        if (ticketCategoriesPerEvent[eventId].length == 0) {
            revert('No categories for this event');
        }
        EventResponse memory eventResponse;
        eventResponse.id = event_.id;
        eventResponse.title = event_.title;
        eventResponse.owner = event_.owner;
        eventResponse.description = event_.description;
        eventResponse.startAt = event_.startAt;
        eventResponse.endAt = event_.endAt;
        eventResponse.eventCategory = event_.eventCategory;
        eventResponse.eventSubcategory = event_.eventSubcategory;
        eventResponse.royalty = event_.royalty;
        eventResponse.baseUri = event_.baseUri;
        eventResponse.location = event_.location;
        eventResponse.ticketCategories = new TicketCategoryResponse[](catlen);

        for (uint256 i = 0; i < catlen; i++) {
            eventResponse.ticketCategories[i] = TicketCategoryResponse({
                id: categories[i].id,
                copies: categories[i].copies,
                ticketCount: categories[i].ticketCount,
                price: categories[i].price,
                name: categories[i].name
            });
        }

        return eventResponse;
    }

    function getEventsByOwner(
        address _owner
    ) external view returns (EventResponse[] memory) {
        uint64[] memory eventIds = ownerEvents[_owner];
        EventResponse[] memory ownerEventsList = new EventResponse[](
            eventIds.length
        );

        for (uint64 i = 0; i < eventIds.length; i++) {
            ownerEventsList[i] = _getEventById(eventIds[i]);
        }

        return ownerEventsList;
    }

    function _processTicketPurchase(
        TicketCategory storage ticketCategory,
        uint64 eventId,
        uint64 categoryId,
        uint128 seatId,
        address eventOwner,
        uint96 eventRoyalty,
        string memory tokenUri
    ) internal {
        require(seatId > 0, 'Seat ID must start from 1');
        require(seatId <= ticketCategory.copies, 'Ticket does not exist');

        for (uint i = 0; i < ticketCategory.seatIds.length; i++) {
            if (ticketCategory.seatIds[i] == seatId) {
                revert('Ticket already bought');
            }
        }

        require(
            ticketCategory.copies > ticketCategory.ticketCount,
            'Not enough tickets available'
        );

        ticketCategory.ticketCount++;
        ticketCategory.seatIds.push(seatId);

        uint256 tokenId = _encodeTokenId(eventId, categoryId, seatId);

        ITicketNFT(ticketContract).mint(
            msg.sender,
            tokenId,
            tokenUri,
            eventOwner,
            eventRoyalty
        );

        emit TicketPurchased(
            TicketPurchasedDto({
                tokenId: tokenId,
                eventId: eventId,
                categoryId: categoryId,
                seatId: seatId,
                createdAt: block.timestamp,
                owner: msg.sender,
                tokenUri: tokenUri
            })
        );
    }

    function _processFeePayment(
        uint256 price,
        address eventOwner,
        address buyer
    ) internal returns (uint256 eventOwnerAmount, uint256 platformFeeAmount) {
        platformFeeAmount = 0;
        eventOwnerAmount = price;

        if (isPlatformFeeEnabled) {
            platformFeeAmount = (price * platformFee) / 10000;
            eventOwnerAmount = price - platformFeeAmount;

            // Transfer platform fee if enabled and greater than 0
            if (platformFeeAmount > 0) {
                require(
                    IERC20(ftContract).transferFrom(
                        buyer,
                        platformFeeReceiver,
                        platformFeeAmount
                    ),
                    'Insufficient payment for platform fee'
                );
            }
        }

        // Transfer payment to event owner
        require(
            IERC20(ftContract).transferFrom(
                buyer,
                eventOwner,
                eventOwnerAmount
            ),
            'Insufficient payment for event owner'
        );

        return (eventOwnerAmount, platformFeeAmount);
    }

    function buyTicket(
        uint64 eventId,
        uint64 categoryId,
        uint128 seatId
    ) external {
        TicketCategory[] storage categories = ticketCategoriesPerEvent[eventId];
        require(categories.length > 0, 'Event does not exist');

        EventResponse memory _event = _getEventById(eventId);

        TicketCategory storage ticketCategory = categories[0];
        bool foundFlag = false;
        for (uint i = 0; i < categories.length; i++) {
            if (categories[i].id == categoryId) {
                foundFlag = true;
                ticketCategory = categories[i];
                break;
            }
        }
        require(foundFlag, 'Ticket category does not exist');

        // Process payment with platform fee
        _processFeePayment(ticketCategory.price, _event.owner, msg.sender);

        _processTicketPurchase(
            ticketCategory,
            eventId,
            categoryId,
            seatId,
            _event.owner,
            _event.royalty,
            _constructTicketUri(_event.baseUri, categoryId, seatId)
        );
    }

    function createMomentCollection(
        CollectionCreationDto calldata collectionCreationDto
    ) external onlyEventOwner(collectionCreationDto.eventId) {
        EventResponse memory _event = _getEventById(
            collectionCreationDto.eventId
        );
        require(block.timestamp > _event.endAt, 'Event has not ended yet');

        uint64 collectionId = uint64(
            momentCollectionPerEvent[collectionCreationDto.eventId].length + 1
        );
        momentCollectionPerEvent[collectionCreationDto.eventId].push(
            SpecialMomentCollection({
                id: collectionId,
                name: collectionCreationDto.name,
                description: collectionCreationDto.description,
                copies: collectionCreationDto.copies,
                royalty: collectionCreationDto.royalty,
                baseUri: collectionCreationDto.baseUri
            })
        );

        uint256[] memory tokenIds = new uint256[](collectionCreationDto.copies);
        address[] memory owners = new address[](collectionCreationDto.copies);

        for (uint128 i = 0; i < collectionCreationDto.copies; i++) {
            uint256 receiverIndex = i % collectionCreationDto.receivers.length;
            uint256 tokenId = _encodeTokenId(
                collectionCreationDto.eventId,
                collectionId,
                i + 1
            );
            tokenIds[i] = tokenId;
            owners[i] = collectionCreationDto.receivers[receiverIndex];
            string memory tokenUri = _constructMomentUri(
                collectionCreationDto.baseUri,
                i + 1
            );
            ISpecialMomentNFT(specialMomentContract).mint(
                collectionCreationDto.receivers[receiverIndex],
                tokenId,
                tokenUri,
                _event.owner,
                collectionCreationDto.royalty
            );
        }

        emit MomentCollectionCreated(
            MomentCollectionCreatedDto({
                collectionId: collectionId,
                eventId: collectionCreationDto.eventId,
                name: collectionCreationDto.name,
                description: collectionCreationDto.description,
                createdAt: block.timestamp,
                baseUri: collectionCreationDto.baseUri,
                tokenIds: tokenIds,
                owners: owners
            })
        );
    }

    // Add this event to the contract
    event MomentCollectionCreated(MomentCollectionCreatedDto momentCollection);

    // Encoding the unique token ID (eventId,categoryId,seatId) or (eventId,collectionId,momentId)
    function _encodeTokenId(
        uint64 eventId,
        uint64 categoryId,
        uint128 seatId
    ) internal pure returns (uint256) {
        return
            (uint256(eventId) << 192) |
            (uint256(categoryId) << 128) |
            uint256(seatId);
    }

    // Decoding the unique token ID
    function _decodeTokenId(
        uint256 tokenId
    )
        internal
        pure
        returns (uint64 eventId, uint64 categoryId, uint128 seatId)
    {
        eventId = uint64(tokenId >> 192);
        categoryId = uint64((tokenId >> 128) & ~uint64(0));
        seatId = uint128(tokenId & ~uint128(0));
    }

    function _constructTicketUri(
        string memory baseUri,
        uint64 categoryId,
        uint256 seatId
    ) internal pure returns (string memory) {
        return
            string(
                abi.encodePacked(
                    baseUri,
                    '/',
                    Strings.toString(categoryId),
                    '/',
                    Strings.toString(seatId)
                )
            );
    }

    function _constructMomentUri(
        string memory baseUri,
        uint256 momentId
    ) internal pure returns (string memory) {
        return
            string(
                abi.encodePacked(
                    baseUri,
                    '/',
                    Strings.toString(momentId),
                    '.json'
                )
            );
    }

    function batchBuyTicket(BatchTicketRequest calldata request) external {
        require(request.tickets.length > 0, 'No tickets provided');

        // Calculate total price and validate tickets
        uint256 totalPrice = 0;

        // First pass: validate all tickets and calculate total price
        for (uint256 i = 0; i < request.tickets.length; i++) {
            TicketRequest memory ticket = request.tickets[i];

            TicketCategory[] storage categories = ticketCategoriesPerEvent[
                ticket.eventId
            ];
            require(categories.length > 0, 'Event does not exist');

            TicketCategory storage ticketCategory = categories[
                ticket.categoryId - 1
            ];

            totalPrice += ticketCategory.price;
        }

        //check allowance
        require(
            IERC20(ftContract).allowance(msg.sender, address(this)) >=
                totalPrice,
            'Insufficient allowance'
        );

        // Second pass: process all tickets
        for (uint256 i = 0; i < request.tickets.length; i++) {
            TicketRequest memory ticket = request.tickets[i];

            EventResponse memory _event = _getEventById(ticket.eventId);
            TicketCategory[] storage categories = ticketCategoriesPerEvent[
                ticket.eventId
            ];

            TicketCategory storage ticketCategory = categories[
                ticket.categoryId - 1
            ];

            _processTicketPurchase(
                ticketCategory,
                ticket.eventId,
                ticket.categoryId,
                ticket.seatId,
                _event.owner,
                _event.royalty,
                _constructTicketUri(
                    _event.baseUri,
                    ticket.categoryId,
                    ticket.seatId
                )
            );
            _processFeePayment(ticketCategory.price, _event.owner, msg.sender);
        }
    }
}

